solution.code:
#include <stdio.h>
#include <stdbool.h>

bool is_odd(int n) {
    return n % 2 != 0;
}

int main() {
    int values[] = {7, 10, -3, -8, 0};
    for (int i = 0; i < 5; i++) {
        printf("%d is %s\n", values[i], is_odd(values[i]) ? "odd" : "even");
    }
    return 0;
}
